    multiCardProbability: 80, maxCardsInComment: 5, useStickerInComment: 15,
    useImageInComment: 15, useKaomojiInComment: 15, useEmojiInComment: 15,
    taCommentOnMyPostProbability: 0,
    likeProbability: 70, likeMinSec: 2, likeMaxSec: 120,
    commentProbability: 70, commentMinSec: 1, commentMaxSec: 60,
    replyProbability: 60, replyMinSec: 1, replyMaxSec: 60,
    returnLikeProbability: 35, taCollectProb: 10,
