  let url = '';
  try { url = URL.createObjectURL(blob); } catch (e) { return 'none'; }
  _saveUrlRelease();
  _saveUrlLast = url;
  try {
    const a = document.createElement('a');
    a.href = url;
    a.download = name || 'download';
    a.rel = 'noopener';
    a.style.cssText = 'position:fixed;left:-9999px;top:0;width:1px;height:1px;opacity:0';
    document.body.appendChild(a);   // ← 必须在文档里：游离节点的 click 在若干国产内核上不生效
    a.click();
    setTimeout(() => { try { if (a.parentNode) a.parentNode.removeChild(a); } catch (e) {} }, 4000);
  } catch (e) { return 'none'; }
