  const d = rec.drag;
  rec.drag = null;
  if (!d) return;
  const el = rec.el;
  const dx = x - d.x;
  const wasMoved = d.moved;
  const speed = d.speed || 0;
  if (!wasMoved || !el.isConnected) return;
  rec.suppressClick = true;
  clearTimeout(rec.suppressTimer);
