      const nm = String(g.name || ''), n = (g.imgs || []).length;
      if (nm === editing) {
        return '<div class="stk-gm-row editing" data-gm="' + escapeHTML(nm) + '">'
          + '<input type="text" class="stk-gm-input" value="' + escapeHTML(nm) + '" maxlength="24" aria-label="分组名">'
          + '<span class="stk-gm-ops"><button type="button" class="stk-gm-btn ok" data-gm-save>保存</button>'
          + '<button type="button" class="stk-gm-btn" data-gm-cancel>取消</button></span></div>';
      }
      if (nm === confirming) {
        return '<div class="stk-gm-row confirm" data-gm="' + escapeHTML(nm) + '">'
          + '<span class="stk-gm-main"><span class="stk-gm-name">删除「' + escapeHTML(nm) + '」？</span>'
          + '<span class="stk-gm-cnt">里面 ' + n + ' 张表情包一起删掉，撤回不了</span></span>'
          + '<span class="stk-gm-ops"><button type="button" class="stk-gm-btn danger" data-gm-delok>删除</button>'
          + '<button type="button" class="stk-gm-btn" data-gm-cancel>取消</button></span></div>';
      }
      return '<div class="stk-gm-row" data-gm="' + escapeHTML(nm) + '">'
        + '<span class="stk-gm-main"><span class="stk-gm-name">' + escapeHTML(nm) + '</span>'
        + '<span class="stk-gm-cnt">' + n + ' 张</span></span>'
