  (data.stickerGroups || []).forEach(g => { if (g && Array.isArray(g.imgs)) g.imgs.forEach(u => { if (typeof u === 'string' && u) imgs.push(u); }); });
  (data.stickers || []).forEach(u => { if (typeof u === 'string' && u) imgs.push(u); });
