  const cur = _gLinkSkins();
  const skins = {};
  Object.keys(cur).forEach(k => { if (cur[k]) skins[k] = cur[k]; });
  if (!Object.keys(skins).length) { showToast('先传几张图再存'); return; }
  let n = 1;
