      g.box.appendChild(el);
      el.classList.add('in');   // 登场回弹（沿对角线错峰）
      el.style.animationDelay = ((Math.floor(i / LINK_COLS) + i % LINK_COLS) * 14) + 'ms';
      setTimeout(() => { el.classList.remove('in'); el.style.animationDelay = ''; }, 1000);
