      const nt = dir === -1 ? turns : (d === dir ? turns : turns + 1);
      if (nt > 2) continue;
      const npath = (dir === -1 || d === dir) ? path : path.concat([[r, c]]);
      if (nr === br && nc === bc) return { turns: nt, pts: npath.concat([[nr, nc]]) };
