  _link.tiles[b] = null;
  _link.left -= 2;
  _link.sel = null;
  let gain = LINK_PAIR_PT;
  const now = Date.now();
  const chained = now - _link.streakAt < 4000;   // 4 秒内连对有小加成
  if (chained) gain += LINK_COMBO_PT;
  _link.streakAt = now;
