    + '--card-hair:' + mix(10) + ';'
    + '--card-fill:' + mix(4) + ';'
    + '--card-pick:' + mix(7) + ';'
    + '--card-on:' + mix(26) + ';'
    + '--card-ring:' + mix(58) + ';'
    + '--card-core:' + mix(80) + ';'
    + '--card-hole:transparent;'
    + '--card-chip-edge:' + mix(20) + ';'
    + '--card-chip-bg:' + mix(8) + '}';
