    const p = (j && j.data && j.data.profile) || (j && j.profile) || null;
    if (!p) { plNcmSayWhy = 'cookie'; showToast('接口答了，但取不到账号＝cookie 多半过期了，重新复制一份 MUSIC_U'); renderPlayerNcm(); return; }
    plNcmSayWhy = '';
