  _plSleepTick();
  { const sb = document.getElementById('plfSleepBtn'), st = document.getElementById('plfSleepTx');
    if (st) { const want = _plSleepGet() ? _plSleepLeftText() : (_plRoot().sleepEnd ? '播完这首' : '定时');
      if (st.textContent !== want) st.textContent = want; }
    if (sb) sb.dataset.on = (_plSleepGet() || _plRoot().sleepEnd) ? '1' : '0'; }
