  const log = (inp && inp.log) || [];
  L.push(log.length ? '键盘沿（最近 6 条）：' + log.slice(-6).map(e => new Date(e.t).toLocaleTimeString('zh-CN') + (e.kb ? ' 开→' + e.h + 'px' : ' 收') + (e.dy ? '∥平移' + e.dy : '')).join(' · ') : '键盘沿：本轮未采到（没弹过键盘＝无沿可记，这一行不是故障）');
  return L;
